export const TurnPuzzle = ({ turns, act = 0.8 }) => {
  // turns: [{request, reply (its end), next, hunch, p, panel, votes (of 3), why}], generated by make_claude_code_data.py
  const LABELS = ["worked", "failed", "redirected", "unclear"];
  const [i, setI] = useState(0);
  const [pick, setPick] = useState(null);
  const t = turns[i];
  const shown = pick !== null;
  const teal = "#7D969B", red = "#C64D35", grey = "rgba(128,128,128,0.25)";
  const box = { borderRadius: 8, padding: "8px 10px", margin: "6px 0", fontSize: 14, lineHeight: 1.5, whiteSpace: "pre-wrap", overflowWrap: "anywhere" };
  const tag = (s) => <div style={{ fontSize: 12, opacity: 0.65, marginBottom: 2 }}>{s}</div>;
  return (
    <div className="not-prose hunch-widget" style={{ border: `1px solid ${grey}`, borderRadius: 12, padding: 16, margin: "16px 0" }}>
      <style>{`.hunch-bar{transition:width .4s ease-out} @media (prefers-reduced-motion: reduce){.hunch-bar{transition:none}}`}</style>
      <div style={{ fontSize: 13, opacity: 0.7 }}>Turn {i + 1} of {turns.length}. How did it go?</div>
      <div style={{ ...box, border: `1px solid ${grey}` }}>{tag("The developer asked")}{t.request}</div>
      <div style={{ ...box, border: `1px solid ${grey}`, fontSize: 13, opacity: 0.85 }}>{tag("The agent ended its turn with")}{t.reply}</div>
      <div style={{ ...box, border: `1px solid ${teal}`, fontWeight: 600 }}>
        <div style={{ fontSize: 12, opacity: 0.65, marginBottom: 2, fontWeight: 400 }}>Then the developer wrote</div>{t.next}
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6, margin: "10px 0 0" }}>
        {LABELS.map((l) => (
          <button key={l} onClick={() => !shown && setPick(l)} disabled={shown}
            style={{ flex: "1 1 70px", padding: "6px 8px", borderRadius: 8, font: "inherit", fontSize: 14, color: "inherit", background: "transparent",
              cursor: shown ? "default" : "pointer",
              border: `1px solid ${shown && l === t.panel ? teal : pick === l ? "currentColor" : grey}` }}>
            {l}{shown && l === t.panel ? " ✓" : ""}{shown && l === pick ? " · you" : ""}
          </button>
        ))}
      </div>
      {shown && (
        <div style={{ fontSize: 14, margin: "12px 0 0", lineHeight: 1.6 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
            <span style={{ minWidth: 150 }}>The question said <b>{t.hunch}</b></span>
            <div style={{ flex: "1 1 120px", height: 6, background: grey, borderRadius: 3 }}>
              <div className="hunch-bar" style={{ width: `${Math.round(t.p * 100)}%`, height: 6, borderRadius: 3, background: t.p >= act ? teal : "rgba(128,128,128,0.55)" }} />
            </div>
            <span style={{ fontVariantNumeric: "tabular-nums" }}>{t.p.toFixed(2)} sure</span>
          </div>
          <p style={{ margin: "6px 0 0" }}>
            {t.p >= act ? `Above the bar of ${act}, so it is labelled without a person.` : `Below the bar of ${act}, so a person checks it.`}{" "}
            The review panel said <b>{t.panel}</b> ({t.votes} of 3).{" "}
            <b style={{ color: pick === t.panel ? teal : red }}>{pick === t.panel ? "You agree with the panel." : "You and the panel differ."}</b>
          </p>
          <p style={{ margin: "6px 0 0" }}>{t.why}</p>
        </div>
      )}
      <div style={{ display: "flex", justifyContent: "flex-end", marginTop: 10 }}>
        <button onClick={() => { setI((i + 1) % turns.length); setPick(null); }}
          style={{ border: `1px solid ${grey}`, borderRadius: 8, padding: "6px 12px", background: "transparent", color: "inherit", font: "inherit", fontSize: 14, cursor: "pointer" }}>
          Next turn →
        </button>
      </div>
    </div>
  );
};

export const GradedTurns = ({ data }) => {
  // data: {act, rows: [[cleared act (0/1), matched the panel (0/1)]]}: one square per graded turn
  const teal = "#7D969B", red = "#C64D35";
  const groups = [["Labelled without a person", data.rows.filter((r) => r[0])], ["Below the bar, sent to a person", data.rows.filter((r) => !r[0])]];
  return (
    <figure className="not-prose" style={{ margin: "16px 0", fontSize: 14 }}>
      {groups.map(([label, rs]) => (
        <div key={label} style={{ margin: "10px 0" }}>
          <div style={{ display: "flex", justifyContent: "space-between", gap: 8, flexWrap: "wrap" }}>
            <span>{label}</span>
            <span><b>{rs.filter((r) => !r[1]).length}</b> wrong of {rs.length}</span>
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 3, marginTop: 5 }} role="img"
            aria-label={`${rs.length} turns, ${rs.filter((r) => !r[1]).length} wrong`}>
            {rs.map((r, k) => (
              <span key={k} style={{ width: 12, height: 12, borderRadius: 3, background: r[1] ? (r[0] ? teal : "rgba(128,128,128,0.35)") : red }} />
            ))}
          </div>
        </div>
      ))}
      <figcaption style={{ fontSize: 13, opacity: 0.7, marginTop: 6 }}>
        One square per graded turn. <span style={{ color: red }}>■</span> the question and the panel disagree.
      </figcaption>
    </figure>
  );
};
